class Ablagefach
{
  private readonly object sperre
      = new();
  private int? wert; // null = leer

  public void Ablegen(int w)
  {
    lock (sperre)
    {
      while (wert != null)
        Monitor.Wait(sperre);
      wert = w;
      Monitor.PulseAll(sperre);
    }
  }
  public int Holen()
  {
    lock (sperre)
    {
      while (wert == null)
        Monitor.Wait(sperre);
      int w = wert.Value;
      wert = null;
      Monitor.PulseAll(sperre);
      return w;
    }
  }
}
